namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();
    private readonly List<Notification> _notifications = [];

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.AddRange(
        [
            MakeNotification("Welcome to the app!"),
            MakeNotification("Your profile was created successfully."),
            MakeNotification("You have a new follower."),
        ]);
    }

    /// <summary>Returns all notifications.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    /// <summary>Returns only notifications newer than the given ID.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>
    /// Simulate new notifications arriving at random.
    /// Called by the background generator so there is something to poll for.
    /// </summary>
    public void TryGenerateRandom()
    {
        if (Random.Shared.Next(0, 3) != 0) return; // ~33 % chance each tick

        string[] templates =
        [
            "New comment on your post",
            "Someone liked your photo",
            "Deployment succeeded",
            "Disk usage above 80 %",
            "Scheduled maintenance tonight",
            "New sign-in from unknown device",
        ];

        lock (_lock)
        {
            _notifications.Add(
                MakeNotification(templates[Random.Shared.Next(templates.Length)]));
        }
    }

    private Notification MakeNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

namespace NotificationsApp.Services;

/// <summary>
/// Hosted service that periodically adds fake notifications
/// so the polling page has something to discover.
/// </summary>
public class NotificationGeneratorService(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(4), stoppingToken);
            notifications.TryGenerateRandom();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject NotificationService NotificationSvc
@inject PersistentComponentState PersistentState

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = [];
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;

    protected override void OnInitialized()
    {
        // If interactive render can restore persisted state, use it and skip the service call.
        _persistSub = PersistentState.RegisterOnPersisting(PersistState);

        if (PersistentState.TryTakeFromJson<List<Notification>>(
                "notifications", out var restored))
        {
            _notifications = restored!;
        }
        else
        {
            // First (static SSR) render — load from service so HTML is complete.
            _notifications = NotificationSvc.GetAll();
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender only fires on interactive renders, never during static SSR.
            _cts = new CancellationTokenSource();
            _ = PollAsync(_cts.Token);
        }
    }

    private async Task PollAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            var lastId = _notifications.Count > 0
                ? _notifications.Max(n => n.Id)
                : 0;

            var newer = NotificationSvc.GetSince(lastId);
            if (newer.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    _notifications.AddRange(newer);
                    StateHasChanged();
                });
            }
        }
    }

    private Task PersistState()
    {
        PersistentState.PersistAsJson("notifications", _notifications);
        return Task.CompletedTask;
    }

    public async ValueTask DisposeAsync()
    {
        _persistSub.Dispose();

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

